func (rt *Router) Use(m Middleware) { rt.chain = append(rt.chain, m) }

func (rt *Router) Delete(path string, h http.HandlerFunc) {
	var handler http.Handler = h
	for i := len(rt.chain) - 1; i >= 0; i-- {
		handler = rt.chain[i](handler)
	}
	rt.mux.Handle("DELETE "+path, handler)
}

func (rt *Router) ServeHTTP(w http.ResponseWriter, r *http.Request) { rt.mux.ServeHTTP(w, r) }

func main() {
	r := NewRouter()
	r.Delete("/users/{id}", deleteUser)
	r.Use(requireAuth)
	r.Delete("/items/{id}", deleteUser)
	http.ListenAndServe(":8080", r)
}

