func requireAuth(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if r.Header.Get("Authorization") == "" {
			http.Error(w, "no", 401)
			return
		}
		next.ServeHTTP(w, r)
	})
}

func resetAll(w http.ResponseWriter, r *http.Request) {}

// serve runs a server until the process is signalled; a nil handler is the default mux.
func serve(ctx context.Context, addr string, h http.Handler) error {
	srv := &http.Server{Addr: addr, Handler: h}
	go func() {
		<-ctx.Done()
		srv.Shutdown(context.Background())
	}()
	return srv.ListenAndServe()
}

func main() {
	ctx, stop := signal.NotifyContext(context.Background(), syscall.SIGTERM)
	defer stop()
	http.HandleFunc("POST /admin/reset", resetAll)
	go serve(ctx, ":9443", requireAuth(http.DefaultServeMux))
	serve(ctx, "127.0.0.1:8080", nil)
}

