func releaseLock(conn *zk.Conn) error {
	_, stat, err := conn.Get("/locks/leader")
	if err != nil {
		return err
	}
	return conn.Delete("/locks/leader", stat.Version)
}

func main() {
	conn, _, _ := zk.Connect([]string{"127.0.0.1"}, time.Second)
	defer releaseLock(conn)
	http.HandleFunc("/health", health)
	http.ListenAndServe(":8080", nil)
}

