package auth

import "net/http"

type Config struct{ Issuer string }

type Authenticator struct{ cfg Config }

func New(cfg Config) *Authenticator { return &Authenticator{cfg: cfg} }

// Middleware rejects unauthenticated requests; with no issuer configured auth is off.
func (a *Authenticator) Middleware(next http.Handler) http.Handler {
	if a.cfg.Issuer == "" {
		return next
	}
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if r.Header.Get("Authorization") == "" {
			http.Error(w, "no", 401)
			return
		}
		next.ServeHTTP(w, r)
	})
}

